readFilterConfig();
var scienceEl = document.getElementById(filterConfig.scienceId);
var courseEl = document.getElementById(filterConfig.courseId);
var classEl = document.getElementById(filterConfig.classId);
if (scienceEl) {
    scienceEl.addEventListener("change", onScienceOrCourseFilterChange);
}
if (courseEl) {
    courseEl.addEventListener("change", onScienceOrCourseFilterChange);
}
if (classEl) {
    classEl.addEventListener("change", onClassFilterChange);
}
